style.css:
@-moz-document domain("roblox.com") {
html,
    body {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* FULL SCREEN BACKGROUND */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;

        background-image: url("https://www.thedailystar.net/sites/default/files/styles/portrait_455x600/public/2026-07/Yamal%20Champion.JPG?h=b2ecd3eb");

        background-size: cover;
        background-position: center center;
        background-repeat: no-repeat;

        z-index: 0;
        pointer-events: none;
    }

    /* DARK GLASS OVERLAY */
    body::after {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;

        background: rgba(0, 0, 0, 0.30);

        z-index: 1;
        pointer-events: none;
    }

    /* MAKE ROBLOX PAGE BACKGROUNDS TRANSPARENT */
    #app,
    #root,
    #container-main,
    #content,
    .rbx-body,
    .content,
    .main-content,
    .page-content,
    .container-main,
    .rbx-left-col {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* KEEP ROBLOX UI ABOVE IMAGE */
    #app,
    #root,
    #container-main,
    #content {
        position: relative;
        z-index: 2;
    }

    /* NAVBAR */
    #navbar {
        background: rgba(10, 10, 15, 0.85) !important;
        backdrop-filter: blur(15px) !important;
        -webkit-backdrop-filter: blur(15px) !important;
    }

    /* SIDEBAR */
    .rbx-left-col {
        background: rgba(8, 10, 16, 0.78) !important;
        backdrop-filter: blur(15px) !important;
        -webkit-backdrop-filter: blur(15px) !important;
    }
}
